// Check if player is currently in Kanto region
static bool8 IsPlayerInKantoRegion(void)
{
    // Check if current map is in Kanto map group
    // MAP_GROUP_KANTO should be generated by the build system
    // For now, we'll use a hardcoded value (assuming Kanto is map group 8)
    return (gSaveBlock1Ptr->location.mapGroup == 8);
}

// Generic HM check function
static bool8 CanUseHMInRegion(u16 hmItem, u16 hoennFlag, u16 kantoFlag)
{
    // Check if player has the HM
    if (!CheckBagHasItem(hmItem, 1))
        return FALSE;
    
    // Check current region and apply appropriate rules
    if (IsPlayerInKantoRegion())
    {
        // In Kanto: Must have Kanto-specific flag
        return CheckFlag(kantoFlag);
    }
    else
    {
        // In Hoenn: Can use if obtained in Hoenn
        return CheckFlag(hoennFlag);
    }
}

// Individual HM check functions
bool8 CanUseHM01Cut(void)
{
    return CanUseHMInRegion(ITEM_HM01, FLAG_HM01_OBTAINED_IN_HOENN, FLAG_HM01_OBTAINED_IN_KANTO);
}

