// Function to get appropriate HM restriction message
const u8* GetHMRegionRestrictionMessage(u16 hmItem)
{
    if (IsPlayerInKantoRegion())
    {
        return gText_HMNotUsableInKanto;
    }
    else
    {
        return gText_HMNotUsableInHoenn;
    }
}

// Function to set HM obtained flag for current region
void SetHMObtainedInCurrentRegion(u16 hmItem)
{
    u16 flagId;
    
    // Determine which flag to set based on HM and current region
    if (IsPlayerInKantoRegion())
    {
        // Set Kanto flag
        switch (hmItem)
        {
        case ITEM_HM01: flagId = FLAG_HM01_OBTAINED_IN_KANTO; break;
        case ITEM_HM02: flagId = FLAG_HM02_OBTAINED_IN_KANTO; break;
        case ITEM_HM03: flagId = FLAG_HM03_OBTAINED_IN_KANTO; break;
        case ITEM_HM04: flagId = FLAG_HM04_OBTAINED_IN_KANTO; break;
        case ITEM_HM05: flagId = FLAG_HM05_OBTAINED_IN_KANTO; break;
        case ITEM_HM06: flagId = FLAG_HM06_OBTAINED_IN_KANTO; break;
        case ITEM_HM07: flagId = FLAG_HM07_OBTAINED_IN_KANTO; break;
        case ITEM_HM08: flagId = FLAG_HM08_OBTAINED_IN_KANTO; break;
        default: return;
        }
    }
    else
    {
        // Set Hoenn flag
        switch (hmItem)
        {
        case ITEM_HM01: flagId = FLAG_HM01_OBTAINED_IN_HOENN; break;
        case ITEM_HM02: flagId = FLAG_HM02_OBTAINED_IN_HOENN; break;
        case ITEM_HM03: flagId = FLAG_HM03_OBTAINED_IN_HOENN; break;
        case ITEM_HM04: flagId = FLAG_HM04_OBTAINED_IN_HOENN; break;
        case ITEM_HM05: flagId = FLAG_HM05_OBTAINED_IN_HOENN; break;
        case ITEM_HM06: flagId = FLAG_HM06_OBTAINED_IN_HOENN; break;
        case ITEM_HM07: flagId = FLAG_HM07_OBTAINED_IN_HOENN; break;
        case ITEM_HM08: flagId = FLAG_HM08_OBTAINED_IN_HOENN; break;
        default: return;
        }
    }
    
    SetFlag(flagId);
}
